import{_ as t,c as a,o as r,a5 as i}from"./chunks/framework.BTBXp1_p.js";const u=JSON.parse('{"title":"ADR-005: OAuthStore Responsibility Reduction","description":"","frontmatter":{},"headers":[],"relativePath":"adr/005-store-responsibility-reduction.md","filePath":"adr/005-store-responsibility-reduction.md","lastUpdated":1769357072000}'),s={name:"adr/005-store-responsibility-reduction.md"};function o(n,e,d,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /oauth-callback/adr/005-store-responsibility-reduction.md for this page in Markdown format</div><h1 id="adr-005-oauthstore-responsibility-reduction" tabindex="-1">ADR-005: OAuthStore Responsibility Reduction <a class="header-anchor" href="#adr-005-oauthstore-responsibility-reduction" aria-label="Permalink to “ADR-005: OAuthStore Responsibility Reduction”">​</a></h1><p><strong>Status:</strong> Accepted <strong>Date:</strong> 2025-01-25 <strong>Tags:</strong> api, storage, simplification</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><p>The store was accumulating OAuth flow state (session, nonce, state parameter) alongside persistent data (tokens, client registration). This blurred the line between &quot;what survives a crash&quot; and &quot;what&#39;s ephemeral by design,&quot; making the API harder to reason about and test.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The store is responsible <strong>only</strong> for data that must survive process restarts:</p><table tabindex="0"><thead><tr><th>Stored</th><th>Not Stored</th></tr></thead><tbody><tr><td><code>tokens</code></td><td><code>state</code> parameter</td></tr><tr><td><code>client</code> (DCR result)</td><td><code>nonce</code></td></tr><tr><td><code>codeVerifier</code> (PKCE)</td><td>session objects</td></tr></tbody></table><p>The <code>codeVerifier</code> is the sole flow artifact persisted—it enables completing an in-progress authorization if the process crashes after browser launch but before callback.</p><h2 id="alternatives-brief" tabindex="-1">Alternatives (brief) <a class="header-anchor" href="#alternatives-brief" aria-label="Permalink to “Alternatives (brief)”">​</a></h2><ul><li><strong>Full session persistence</strong> — Would enable crash-recovery at any point, but adds complexity for a rare edge case. Users can simply restart the flow.</li><li><strong>No verifier persistence</strong> — Simpler, but loses the most common crash scenario (user switches apps, process dies).</li></ul><h2 id="impact" tabindex="-1">Impact <a class="header-anchor" href="#impact" aria-label="Permalink to “Impact”">​</a></h2><ul><li>Positive: Cleaner mental model; store implementations are trivial to write and test.</li><li>Negative: If the process crashes before <code>codeVerifier</code> is saved, the flow must restart. This is acceptable—it&#39;s a sub-second window.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to “Links”">​</a></h2><ul><li>Code: <code>src/storage/</code>, <code>src/mcp-types.ts</code></li><li>Related: ADR-002 (Immediate Token Exchange)</li></ul>',15)])])}const b=t(s,[["render",o]]);export{u as __pageData,b as default};
